using System.Runtime.CompilerServices;
using System.Text.Json.Nodes;
using Aether;
using Xunit;

namespace Aether.Tests;

// Wire-contract parity against the shared golden fixtures in testdata/wire. The fixtures are
// generated by the Go source of truth (internal/wire: go test -run TestEnvelopeGolden -update) and
// consumed by every SDK. Field order and whitespace differ between languages, so we compare parsed
// values, not bytes - the same stance as sdk/python/wire_parity_test.py.
public class WireParityTests
{
    private static string GoldenDir([CallerFilePath] string thisFile = "")
        => Path.GetFullPath(Path.Combine(
            Path.GetDirectoryName(thisFile)!, "..", "..", "..", "testdata", "wire"));

    public static TheoryData<string> GoldenFiles()
    {
        var data = new TheoryData<string>();
        foreach (var path in Directory.EnumerateFiles(GoldenDir(), "*.json"))
        {
            data.Add(Path.GetFileName(path));
        }
        return data;
    }

    [Fact]
    public void GoldenDir_HasFixtures()
    {
        // Guard against a vacuous pass if the fixtures move or the path math is wrong.
        Assert.True(Directory.EnumerateFiles(GoldenDir(), "*.json").Count() >= 10);
    }

    [Theory]
    [MemberData(nameof(GoldenFiles))]
    public void Golden_RoundTrips(string fileName)
    {
        // Decode a fixture into the typed envelope and re-encode it; the result must be value-equal
        // to the fixture. A wrong field name drops data (mismatch), a wrong omitempty adds or loses
        // a key (mismatch), a wrong type fails to parse - so this one check covers the whole shape.
        var original = File.ReadAllBytes(Path.Combine(GoldenDir(), fileName));

        var envelope = Json.Decode<Envelope>(original)!;
        var reencoded = Json.Encode(envelope);

        Assert.True(
            JsonNode.DeepEquals(JsonNode.Parse(original), JsonNode.Parse(reencoded)),
            $"{fileName}: re-encoded envelope differs from the golden fixture");
    }

    [Fact]
    public void Subjects_MatchContract()
    {
        const string app = "demo";
        const string name = "counter";
        Assert.Equal("aether.demo.counter.call", Subjects.Call(app, name));
        Assert.Equal("aether.demo.counter.cast", Subjects.Cast(app, name));
        Assert.Equal("aether.demo.counter.info", Subjects.Info(app, name));
        Assert.Equal("aether.demo.counter.*", Subjects.Data(app, name));
        Assert.Equal("aether_demo_counter", Subjects.Stream(app, name));
        Assert.Equal("aether.demo.counter.evt", Subjects.EventLog(app, name));
        Assert.Equal("aether_demo_counter_evt", Subjects.EventLogStream(app, name));
        Assert.Equal("aether._lord.counter.ctl", Subjects.Ctl(name));
        Assert.Equal("aether._lord.counter.hb", Subjects.Heartbeat(name));
        Assert.Equal("aether._lord.ctl", Subjects.LordCtl());
        Assert.Equal("aether._lord.events", Subjects.Events);
        Assert.Equal("aether._fleet.demo.lord-1", Subjects.FleetHealth(app, "lord-1"));
    }
}
